import 'package:a2ui_flutter/a2ui_flutter.dart';
import 'package:flutter/material.dart';
import 'package:flutter_markdown_plus/flutter_markdown_plus.dart';

import 'a2ui_chat_controller.dart';

/// A self-contained chat view backed by an [McpA2uiChatController].
///
/// It renders the conversation transcript (user/assistant text), the active
/// A2UI surfaces generated by the model via [A2uiSurface], and an input bar.
class A2uiChatView extends StatefulWidget {
  /// Creates an [A2uiChatView].
  const A2uiChatView({
    super.key,
    required this.controller,
    this.title = 'A2UI Chat',
    this.inputHint = 'Message',
    this.chatBackgroundDecoration,
    this.showEmptyChatState = true,
    this.emptyChatBuilder,
  });

  /// The controller driving the conversation.
  final McpA2uiChatController controller;

  /// The title shown in the app bar.
  final String title;

  /// The hint text for the message input.
  final String inputHint;

  /// Optional background decoration for the chat view.
  final Decoration? chatBackgroundDecoration;

  /// Whether to show the empty chat state. Defaults to true.
  final bool showEmptyChatState;

  /// Optional custom builder for the empty chat state.
  final WidgetBuilder? emptyChatBuilder;

  @override
  State<A2uiChatView> createState() => _A2uiChatViewState();
}

class _A2uiChatViewState extends State<A2uiChatView> {
  final TextEditingController _inputController = TextEditingController();
  final ScrollController _scrollController = ScrollController();

  @override
  void initState() {
    super.initState();
    widget.controller.addListener(_onControllerChanged);
  }

  @override
  void dispose() {
    widget.controller.removeListener(_onControllerChanged);
    _inputController.dispose();
    _scrollController.dispose();
    super.dispose();
  }

  void _onControllerChanged() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_scrollController.hasClients) return;
      _scrollController.jumpTo(_scrollController.position.maxScrollExtent);
    });
  }

  void _send() {
    final text = _inputController.text;
    if (text.trim().isEmpty) return;
    widget.controller.sendMessage(text);
    _inputController.clear();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(widget.title)),
      body: Column(
        children: [
          Expanded(child: _buildTranscript(context)),
          _buildInput(context),
        ],
      ),
    );
  }

  Widget _buildTranscript(BuildContext context) {
    return Container(
      decoration: widget.chatBackgroundDecoration,
      child: AnimatedBuilder(
        animation: widget.controller,
        builder: (context, _) {
          final entries = widget.controller.entries;
          if (entries.isEmpty) {
            if (widget.emptyChatBuilder != null) {
              return widget.emptyChatBuilder!(context);
            }
            if (!widget.showEmptyChatState) {
              return const SizedBox.expand();
            }
            return const Center(
              child: Text(
                'Start a conversation to generate interactive A2UI widgets.',
                style: TextStyle(color: Colors.grey),
              ),
            );
          }

          return ListView.builder(
            controller: _scrollController,
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 12),
            itemCount: entries.length,
            itemBuilder: (context, index) {
              return _buildEntry(context, entries[index]);
            },
          );
        },
      ),
    );
  }

  Widget _buildEntry(BuildContext context, A2uiChatEntry entry) {
    switch (entry.kind) {
      case A2uiChatEntryKind.user:
        return _bubble(context, entry.text, isUser: true);
      case A2uiChatEntryKind.assistant:
        if (entry.text.trim().isEmpty) return const SizedBox.shrink();
        return _bubble(context, entry.text, isUser: false);
      case A2uiChatEntryKind.surface:
        if (entry.surfaceId != null) {
          return _buildSurface(context, entry.surfaceId!);
        }
        return const SizedBox.shrink();
      case A2uiChatEntryKind.error:
        return Container(
          margin: const EdgeInsets.symmetric(vertical: 6, horizontal: 12),
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: Theme.of(context).colorScheme.errorContainer.withValues(alpha: 0.3),
            borderRadius: BorderRadius.circular(12),
          ),
          child: Text(
            entry.text,
            style: TextStyle(
              color: Theme.of(context).colorScheme.onErrorContainer,
              fontFamily: 'monospace',
              fontSize: 12,
            ),
          ),
        );
    }
  }

  Widget _bubble(BuildContext context, String text, {required bool isUser}) {
    final theme = Theme.of(context);
    final isDark = theme.brightness == Brightness.dark;
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 4, horizontal: 12),
      child: Row(
        mainAxisAlignment: isUser ? MainAxisAlignment.end : MainAxisAlignment.start,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (!isUser) ...[
            CircleAvatar(
              radius: 14,
              backgroundColor: isDark
                  ? Colors.white.withValues(alpha: 0.1)
                  : theme.colorScheme.primaryContainer,
              child: Icon(
                Icons.smart_toy_outlined,
                size: 16,
                color: isDark
                    ? Colors.white
                    : theme.colorScheme.onPrimaryContainer,
              ),
            ),
            const SizedBox(width: 8),
          ],
          Flexible(
            child: Container(
              padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 14),
              decoration: BoxDecoration(
                color: isUser
                    ? theme.colorScheme.primary.withValues(alpha: 0.15)
                    : (isDark
                        ? Colors.white.withValues(alpha: 0.05)
                        : Colors.black.withValues(alpha: 0.04)),
                borderRadius: BorderRadius.circular(16),
              ),
              child: isUser
                  ? SelectableText(text)
                  : MarkdownBody(data: text, selectable: true),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildSurface(BuildContext context, String surfaceId) {
    final surfaceModel = widget.controller.surfaceFor(surfaceId);
    if (surfaceModel == null) return const SizedBox.shrink();

    return Card(
      margin: const EdgeInsets.symmetric(vertical: 8, horizontal: 12),
      elevation: 2,
      child: Padding(
        padding: const EdgeInsets.all(12),
        child: A2uiSurface(surface: surfaceModel),
      ),
    );
  }

  Widget _buildInput(BuildContext context) {
    return SafeArea(
      top: false,
      child: Padding(
        padding: const EdgeInsets.all(8),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.end,
          children: [
            Expanded(
              child: TextField(
                controller: _inputController,
                minLines: 1,
                maxLines: 4,
                decoration: InputDecoration(
                  hintText: widget.inputHint,
                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(24)),
                  contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                ),
                onSubmitted: (_) => _send(),
              ),
            ),
            const SizedBox(width: 8),
            AnimatedBuilder(
              animation: widget.controller,
              builder: (context, _) {
                final isGenerating = widget.controller.isGenerating;
                return IconButton.filled(
                  icon: Icon(isGenerating ? Icons.stop : Icons.send),
                  onPressed: isGenerating ? widget.controller.stopGeneration : _send,
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}

